import{_ as o,a0 as n,w as p,s as d,I as t,x as i,a1 as l,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何從命令列同時移動多種文件類型 | LCTT x X-CMD","titleTemplate":false,"description":"如何從命令列同時移動多種文件類型 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從命令列同時移動多種文件類型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從命令列同時移動多種文件類型 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline","title":"如何從命令列同時移動多種文件類型","tag":"201901","desc":""},"relativePath":"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline.md","filePath":"[post].md"}'),h={name:"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline.md"};function u(g,s,m,k,c,f){const e=n("Link");return p(),d("div",null,[s[18]||(s[18]=t("h1",{id:"如何從命令列同時移動多種文件類型",tabindex:"-1"},[i("如何從命令列同時移動多種文件類型 "),t("a",{class:"header-anchor",href:"#如何從命令列同時移動多種文件類型","aria-label":"Permalink to “如何從命令列同時移動多種文件類型”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/01/Move-Multiple-File-Types-720x340.png",alt:""})],-1)),t("p",null,[s[1]||(s[1]=i("前幾天，我想知道如何將多個文件類型從一個目錄移動（不復制）到另一個目錄。我已經知道如何",-1)),l(e,{href:"https://www.ostechnix.com/find-copy-certain-type-files-one-directory-another-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("查找並將某些類型的文件從一個目錄複製到另一個目錄",-1)])]),_:1}),s[2]||(s[2]=i("。但是，我不知道如何同時移動多種文件類型。如果你曾遇到這樣的情況，我知道在類 Unix 系統中從命令列執行該操作的一個簡單方法。",-1))]),s[20]||(s[20]=r(`<h3 id="同時移動多種文件類型" tabindex="-1">同時移動多種文件類型 <a class="header-anchor" href="#同時移動多種文件類型" aria-label="Permalink to “同時移動多種文件類型”">​</a></h3><p>想像一下這種場景，你在名為 <code>dir1</code> 的目錄中有多種類型的文件，例如 .pdf、 .doc、 .mp3、 .mp4、 .txt 等等。我們來看看 <code>dir1</code> 的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls dir1</span></span>
<span class="line"><span>file.txt image.jpg mydoc.doc personal.pdf song.mp3 video.mp4</span></span></code></pre></div><p>你希望將某些文件類型（不是所有文件類型）移動到另一個位置。例如，假設你想將 .doc、 .pdf 和 .txt 文件一次性移動到名為 <code>dir2</code> 的另一個目錄中。</p><p>要同時將 .doc、 .pdf 和 .txt 文件從 <code>dir1</code> 移動到 <code>dir2</code>，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv dir1/*.{doc,pdf,txt} dir2/</span></span></code></pre></div><p>很容易，不是嗎？</p><p>現在讓我們來查看一下 <code>dir2</code> 的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls dir2/</span></span>
<span class="line"><span>file.txt mydoc.doc personal.pdf</span></span></code></pre></div><p>看到了嗎？只有 .doc、 .pdf 和 .txt 從 <code>dir1</code> 移到了 <code>dir2</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/mv-command.gif" alt=""></p><p>在上面的命令中，你可以在花括號內添加任意數量的文件類型，以將它們移動到不同的目錄中。它在 Bash 上非常適合我。</p><p>另一種移動多種文件類型的方法是轉到源目錄，在我們的例子中即為 <code>dir1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/dir1</span></span></code></pre></div><p>將你選擇的文件類型移動到目的地（即 <code>dir2</code>），如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv *.doc *.txt *.pdf /home/sk/dir2/</span></span></code></pre></div><p>要移動具有特定擴展名的所有文件，例如 .doc，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv dir1/*.doc dir2/</span></span></code></pre></div><p>更多細節，參考 man 頁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mv</span></span></code></pre></div><p>移動一些相同或不同的文件類型很容易！你可以在 GUI 模式下單擊幾下鼠標，或在 CLI 模式下使用一行命令來完成。但是，如果目錄中有數千種不同的文件類型，並且希望一次將多種文件類型移動到不同的目錄，這將是一項繁瑣的任務。對我來説，上面的方法很容易完成工作！如果你知道任何其它一行命令可以一次移動多種文件類型，請在下面的評論部分與我們分享。我會核對並更新指南。</p><p>這些就是全部了，希望這很有用。更多好東西將要來了，敬請關注！</p><p>共勉！</p><hr>`,24)),t("p",null,[s[4]||(s[4]=i("via: ",-1)),l(e,{href:"https://www.ostechnix.com/how-to-move-multiple-file-types-simultaneously-from-commandline/"},{default:a(()=>[...s[3]||(s[3]=[i("https://www.ostechnix.com/how-to-move-multiple-file-types-simultaneously-from-commandline/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[i("SK",-1)])]),_:1}),s[10]||(s[10]=i(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 譯者：",-1)),l(e,{href:"https://github.com/MjSeven"},{default:a(()=>[...s[7]||(s[7]=[i("MjSeven",-1)])]),_:1}),s[12]||(s[12]=i(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=i("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中國",-1)])]),_:1}),s[17]||(s[17]=i(" 榮譽推出",-1))])])}const C=o(h,[["render",u]]);export{x as __pageData,C as default};
